import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
const read = path => readFileSync(path, 'utf8')
const report = read('worker/domains/finance-reports.ts')
const renderer = read('src/features/renderers/FinanceReportContentRenderer.tsx')
const explorer = read('src/features/renderers/CityOrdersExplorer.tsx')
const app = read('src/App.tsx')
const server = read('worker/index.ts')
const auth = read('worker/domains/auth.ts')
const team = read('worker/domains/team.ts')
const norm = read('worker/core/text.ts')
const assertHas = (source, term) => assert.ok(source.includes(term), 'Missing: '+term)

assertHas(report, 'export async function listCityReportOrders')
assertHas(report, "AND o.order_status <> 'deleted'")
assertHas(report, "AND COALESCE(NULLIF(o.city, ''), 'Не указан') = ?")
assertHas(report, 'ORDER BY o.order_date DESC, o.id DESC')
assertHas(report, 'LIMIT ? OFFSET ?')
assertHas(report, 'hasMore: rows.length > limit')
assertHas(server, "url.pathname === '/api/reports/city-orders'")
assertHas(explorer, "limit: '25'")
assertHas(explorer, 'createPortal(')
assertHas(renderer, '<CityOrdersExplorer')
assertHas(renderer, 'id="selectedFinanceReportExport"')
assertHas(app, 'financeReportContentCtx: { apiFetch, exportSelectedFinanceReportWord')
assertHas(team, 'includeBirthDate = false')
assertHas(team, 'includeBirthDate ? { birthDate:')
assertHas(server, "listTeamEmployees(env.DB, authUser?.role === 'admin')")
assertHas(team, 'birth_date')
assertHas(norm, "return 'Упаковщик'")
assertHas(norm, "return 'Завсклад'")
assertHas(auth, "m.role AS employee_role, m.is_active AS employee_is_active")
assertHas(auth, 'employeeRole: toInt(row.employee_is_active, 0) === 1')
assertHas(server, "authUser.employeeRole === 'Завсклад' && warehouseSupervisorEndpoint")
assertHas(app, "authUser?.employeeRole === 'Завсклад'")
const policy = server.slice(server.indexOf('function warehouseSupervisorEndpoint('),server.indexOf('export default {'))
assert.ok(policy.length > 100)
assert.ok(!policy.includes('api\\/orders'), 'Supervisor scope must exclude order admin APIs')
assert.ok(!policy.includes('api\\/auth'), 'Supervisor scope must exclude account management')
assert.ok(!policy.includes('api\\/finance'), 'Supervisor scope must exclude finance')
assertHas(read('migrations/0115_team_birth_date.sql'), 'ALTER TABLE managers ADD COLUMN birth_date TEXT')
console.log('CITY_TEAM_WAREHOUSE_STATIC_INVARIANTS_PASS')
